#!/usr/bin/env node
/**
 * Validate every Flow XML generated by the Config Library's "Copy Flow XML"
 * button against resilient-badger. Process:
 *
 *  1. Load js/config-actions.js into a sandbox (stub document so the IIFE
 *     doesn't crash; capture the buildFlowXml function via global).
 *  2. For each downloads/configs/*.json, generate the Flow XML the user
 *     would see when clicking "Copy Flow XML".
 *  3. Write each XML to tmp/flow-validate/{name}.flow-meta.xml inside a
 *     minimal sfdx project so `sf project deploy validate` can find them.
 *  4. Run `sf project deploy validate` per file against resilient-badger.
 *
 * Exit 0 if all pass; exit 1 with summary if any fail.
 */
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const { execSync } = require('child_process');

const ROOT = path.resolve(__dirname, '..');
const CONFIG_DIR = path.join(ROOT, 'downloads', 'configs');
const JS_FILE = path.join(ROOT, 'js', 'config-actions.js');
const TMP_DIR = path.join(ROOT, 'tmp', 'flow-validate');
const TMP_FLOWS = path.join(TMP_DIR, 'force-app', 'main', 'default', 'flows');

// ── set up sandbox with stubbed DOM so the IIFE in config-actions.js loads ──
const sandbox = {
    document: {
        getElementById: () => null,
        createElement: () => ({ style: {}, appendChild: () => {} }),
        querySelectorAll: () => [],
        addEventListener: () => {},
        body: { appendChild: () => {} },
    },
    window: {},
    console,
    setTimeout: () => {},
    captured: {},
};
sandbox.window.document = sandbox.document;
vm.createContext(sandbox);

// Inject a hook before the IIFE runs that captures buildFlowXml when defined
const jsContent = fs.readFileSync(JS_FILE, 'utf-8');

// Modify the IIFE to write buildFlowXml to global before the auto-bind
const patched = jsContent.replace(
    /\}\)\(\);\s*$/,
    'captured.buildFlowXml = buildFlowXml;\ncaptured.buildInputParams = buildInputParams;\ncaptured.buildBookingFlow = buildBookingFlow;\ncaptured.buildDatesOrDateTimeFlow = buildDatesOrDateTimeFlow;\n})();'
);
vm.runInContext(patched, sandbox);
const buildFlowXml = sandbox.captured.buildFlowXml;
if (typeof buildFlowXml !== 'function') {
    console.error('FAIL: could not extract buildFlowXml from config-actions.js');
    process.exit(2);
}

// ── set up tmp sfdx project ──
fs.mkdirSync(TMP_FLOWS, { recursive: true });
fs.writeFileSync(
    path.join(TMP_DIR, 'sfdx-project.json'),
    JSON.stringify({
        packageDirectories: [{ path: 'force-app', default: true }],
        namespace: '',
        sfdcLoginUrl: 'https://login.salesforce.com',
        sourceApiVersion: '63.0',
    }, null, 2)
);

// ── generate + validate ──
const configFiles = fs.readdirSync(CONFIG_DIR).filter(f => f.endsWith('.json'));
console.log(`Found ${configFiles.length} config files. Generating + validating...`);

const results = { pass: [], fail: [] };

for (const cf of configFiles) {
    const configName = cf.replace('.json', '');
    const cfgPath = path.join(CONFIG_DIR, cf);
    let cfg;
    try {
        cfg = JSON.parse(fs.readFileSync(cfgPath, 'utf-8'));
    } catch (e) {
        results.fail.push({ name: configName, stage: 'parse-json', error: e.message });
        continue;
    }
    const componentType = cfg.Component_Type__c || 'Dates';
    let xml;
    try {
        xml = buildFlowXml(cfg, componentType, configName);
    } catch (e) {
        results.fail.push({ name: configName, stage: 'generate-xml', error: e.message });
        continue;
    }
    const flowFile = path.join(TMP_FLOWS, configName + '.flow-meta.xml');
    fs.writeFileSync(flowFile, xml);
}

console.log(`Wrote ${configFiles.length} flow files. Running sf deploy validate per file...`);

for (const cf of configFiles) {
    const configName = cf.replace('.json', '');
    const flowFile = path.join('force-app', 'main', 'default', 'flows', configName + '.flow-meta.xml');
    try {
        const targetOrg = process.env.TARGET_ORG || 'resilient-badger';
        const cmd = `sf project deploy validate --source-dir "${flowFile}" --target-org ${targetOrg} --json`;
        const raw = execSync(cmd, {
            cwd: TMP_DIR,
            encoding: 'utf-8',
            stdio: ['ignore', 'pipe', 'pipe'],
            timeout: 120000,
        });
        const parsed = JSON.parse(raw);
        const success = parsed.status === 0 && parsed.result && parsed.result.status !== 'Failed';
        if (success) {
            results.pass.push(configName);
            process.stdout.write('.');
        } else {
            const errs = (parsed.result && parsed.result.details && parsed.result.details.componentFailures) || [];
            results.fail.push({
                name: configName,
                stage: 'validate',
                error: errs.slice(0, 3).map(e => `${e.problemType}: ${e.problem}`).join(' | ') || 'unknown',
            });
            process.stdout.write('F');
        }
    } catch (e) {
        let detail = e.message;
        if (e.stdout) {
            try {
                const p = JSON.parse(e.stdout.toString());
                const errs = (p.result && p.result.details && p.result.details.componentFailures) || [];
                if (errs.length) {
                    detail = errs.slice(0, 3).map(e => `${e.problemType}: ${e.problem}`).join(' | ');
                } else if (p.message) {
                    detail = p.message;
                }
            } catch (_) { /* leave detail */ }
        }
        results.fail.push({ name: configName, stage: 'validate-exec', error: detail.slice(0, 300) });
        process.stdout.write('F');
    }
}

console.log('\n');
console.log('═══════════════════════════════════════════════');
console.log(`PASS: ${results.pass.length}  FAIL: ${results.fail.length}  / 32`);
console.log('═══════════════════════════════════════════════');
if (results.fail.length) {
    console.log('\nFailures:');
    for (const f of results.fail) {
        console.log(`  ✗ ${f.name} [${f.stage}]`);
        console.log(`      ${f.error}`);
    }
    process.exit(1);
}
console.log('\nAll 32 flow XMLs validated successfully against resilient-badger.');
